-- CreateTable for Food
CREATE TABLE "Food" (
  "id" TEXT NOT NULL PRIMARY KEY,
  "name" TEXT NOT NULL,
  "state" TEXT NOT NULL,
  "foodGroupId" TEXT NOT NULL,

  -- Composition per 100g
  "calories" REAL,
  "protein" REAL,
  "fat" REAL,
  "carbohydrates" REAL,
  "water" REAL,
  "nitrogen" REAL,

  -- Vitamins per 100g
  "vitaminA_ui" REAL,
  "vitaminB1_mcg" REAL,
  "vitaminB2_mcg" REAL,
  "vitaminC_mcg" REAL,
  "niacin_mcg" REAL,

  -- Minerals
  "sodium_mg" REAL,
  "potassium_mg" REAL,
  "calcium_mg" REAL,
  "magnesium_mg" REAL,
  "iron_mg" REAL,
  "copper_mg" REAL,
  "phosphorus_mg" REAL,
  "sulfur_mg" REAL,
  "chloride_mg" REAL,

  -- Amino acids
  "phenylalanine_mg" REAL,
  "isoleucine_mg" REAL,
  "leucine_mg" REAL,
  "lysine_mg" REAL,
  "methionine_mg" REAL,
  "threonine_mg" REAL,
  "tryptophan_mg" REAL,
  "valine_mg" REAL,

  "acid" REAL,
  "alcal" REAL,

  CONSTRAINT "Food_foodGroupId_fkey" FOREIGN KEY ("foodGroupId") REFERENCES "FoodGroup" ("id") ON DELETE RESTRICT ON UPDATE CASCADE
);


